'use client';

// =============================================================================
// PlanBoard — adapter del board /plan para el super-admin (localStorage)
// =============================================================================
// Toda la UI vive en board/BoardShell (compartida con el cliente). Acá: los
// PROYECTOS FINITOS (inicio/fin, deadline, descripción rica) + sus tareas — el
// roadmap real de MaKo minado del historial de git + la memoria — la carga/
// persistencia en localStorage y el Repo. Un proyecto es una INICIATIVA FINITA,
// no un área infinita.

import { useEffect, useState } from 'react';
import { BoardShell } from './board/BoardShell';
import { useBoard } from './board/useBoard';
import { type BoardTask, type Label, type Repo, type BoardUser, type Prio, type Hist, scoreFromPrio, prioFromScore, clampScore } from './board/types';

const K6 = 'mako_plan_v6', K_PROJS = 'mako_plan_projs_v4';
const SEED_TS = Date.parse('2026-07-13T12:00:00Z');

const P = (id: string, emoji: string, name: string, color: string, score: number, scoreRazon: string, detalle: string, deadline: string): Label =>
  ({ id, emoji, name, color, score, scoreRazon: scoreRazon || undefined, deadline: deadline || undefined, detalle, historial: [{ id: 'seedp' + id, ts: SEED_TS, actor: 'ia', text: 'Creó el proyecto' }] });

// ── Proyectos FINITOS (minados de git + memoria; prioridad 1-10, deadline, descripción) ──
const PROJS_DEFAULT: Label[] = [
  P("tooluse-core-de", "🧠", "Tool-Use Core de MaKo (loop agéntico + doer)", "#D0504A", 10, "El candado de todo lo accionable:", "El candado de todo lo accionable: MaKo pasa de one-shot (chatClaude sin herramientas, opinando sin ver la data) a un loop agéntico real (chatClaudeTools) con un registro de tools tenant-scoped. Primero LECTURA (consulta el negocio antes de responder), después PROPUESTA (arma borradores que vos aprobás por un caller gateado, nunca por un send* pelado), y presencia CONTEXTUAL en cada tab. Sin este cimiento no hay Retro que reclame, ni semáforo que accione, ni CRM que se explique. Se ve terminado cuando MaKo lee todo el negocio, ve números vivos y propone acciones concretas embebido en cada pantalla.", "2026-08-31"),
  P("golive-encender-el", "🚀", "Go-live: encender el producto para el primer cliente real", "#2F6FED", 10, "El cuello de botella entre 'código listo' y 'producto que actúa':", "El cuello de botella entre 'código listo' y 'producto que actúa': todo el motor corre en dry-run y nada sale de verdad. Encender SELECTIVA y seguramente lo construido pero apagado (nutrición, email, WhatsApp oficial y no oficial, CRM-auto) por workspace, sin quemar pasos ni molestar a otros clientes, y sin perder datos irreversibles de Meta. Se ve terminado cuando un workspace piloto corre con envío real ON, dominio verificado, Evolution conectado y una plantilla WA aprobada en vivo.", "2026-07-31"),
  P("crm-automtico-leads", "🤖", "CRM Automático: leads que avanzan solos", "#0E9B8E", 9, "MaKo mueve el lead de etapa solo con la lógica de un buen closer:", "MaKo mueve el lead de etapa solo con la lógica de un buen closer: agenda una R1 y a las 3h revisa Fathom para saber si asistió, deriva a nutrición al que no agenda, marca No Show, reactiva al enfriado. Motor de 6 reglas (T1–T6) con principios fill-if-empty (nunca pisa dato humano), rastro en lead_audit con autor 'MaKo' y apply-then-confirm (aplica y pide OK con un modal no cerrable). El esquema, el planner, la fase de aplicación con red de confirmaciones y los templates de nutrición ya están en prod, gateados en dry-run. Se ve terminado cuando se enciende por workspace y mueve leads reales sin quemar pólvora.", "2026-08-20"),
  P("recordatorios-de-juntas", "⏰", "Recordatorios de juntas + follow-ups (retirar n8n)", "#7C5CFB", 9, "Reconstruir DENTRO de la app el seguimiento que hoy vive en n8n sobre OTRO Supabase y está apagado:", "Reconstruir DENTRO de la app el seguimiento que hoy vive en n8n sobre OTRO Supabase y está apagado: recordatorios de juntas (24h/1h/15m), follow-ups FU1-3, dunning de cobranza y follow-up post-llamada, reusando el motor de nutrición. Importa porque el no-show es el asesino nº1 del high-ticket y hoy la nutrición automática casi no corre. Ataca el split-brain (dos bases que no se cruzan, Calendly procesado por ambos). Se ve terminado cuando la app manda recordatorios y follow-ups sola y se retira el workflow de n8n.", "2026-08-20"),
  P("cerrar-la-auditora", "🛡️", "Cerrar la auditoría de seguridad multi-tenant", "#C8870C", 9, "Llevar a cero los hallazgos OWASP+STRIDE antes de onboardear clientes reales.", "Llevar a cero los hallazgos OWASP+STRIDE antes de onboardear clientes reales. Importa porque el anti-patrón raíz (getSupabaseServer crudo sobre tablas tenant) filtra datos cross-workspace y quedan superficies sin cubrir. Terminado cuando no hay ningún leak cross-tenant, las acciones operativas están aplicadas en Vercel/Supabase, y la CSP + los webhooks están endurecidos. Los 4 HIGH y los medium/low ya están fixeados; falta la cola larga.", "2026-07-25"),
  P("ficha-del-lead", "🪪", "Ficha del lead — rediseño integral (v5 + auditoría + batch 2)", "#D6489B", 8, "El rediseño completo del detalle del lead:", "El rediseño completo del detalle del lead: los 15 puntos de v5 (wizard de movimiento estilo campaña MaKo, tabs Overview/Tracking/Meetings/Deal Details/Change History, cuotas explícitas, contrato leído por IA, tracking granular, tab Chat, Insights generativo, 'automático primero'), la auditoría multi-agente que fusionó todo a una ficha ÚNICA (modal + /leads/[id]), y el batch 2 (Datos sin marcar, Closer/Setter con foto, wizard Solucionar). Se ve terminado cuando abrir un lead cuenta toda su historia en una sola ficha, editable por gesto, con MaKo redactando lo que falta. Casi todo entregado; quedan colas de deuda.", ""),
  P("multiinquilino-workspace", "🏢", "Multi-inquilino (workspaces aislados)", "#1E9E57", 8, "Migrar el dashboard de single-tenant (todos veían los datos de Mauricio) a multi-inquilino:", "Migrar el dashboard de single-tenant (todos veían los datos de Mauricio) a multi-inquilino: cada usuario = su propio workspace aislado, con panel de agencia para 'entrar como' cualquier cliente y cada cliente corriendo con SUS credenciales e ingesta. Importa porque sin aislamiento no se puede vender MaKo a un segundo cliente sin filtrar datos ajenos. El núcleo (Fase 1/2/2b) está entregado y verificado en prod.", ""),
  P("retro-real-rendicin", "🔎", "Retro real + Rendición de cuentas", "#98A0AC", 8, "La Retro es el único cerebro integral de MaKo:", "La Retro es el único cerebro integral de MaKo: lee todo el negocio por áreas, da veredictos, propone experimentos/tareas y con 'Aceptar' los CREA de verdad (idempotente). Pero la rendición de cuentas es hoy FALSA: armarSeguimiento mira el status del CLICK, no la ejecución real, y el retro_id que se persiste nunca se vuelve a leer. Este proyecto cierra el loop: que MaKo detecte fugas con la metodología Recon, verifique lo que EJECUTASTE contra lo prometido, te lo reclame y no re-proponga lo que ya ignoraste. Se ve terminado cuando la Retro deja de ser un informe caro on-demand y pasa a ser un coach que te persigue.", "2026-08-25"),
  P("pulso-diario-vista", "💓", "Pulso diario: vista Hoy + semáforo vivo + latido", "#D0504A", 7, "El órgano que a los pilares del doer les falta por igual:", "El órgano que a los pilares del doer les falta por igual: un LATIDO barato y periódico que lee qué se hizo de verdad, razona liviano y te reclama/avisa por campanita + WhatsApp. En vez de un dashboard que abruma, una vista 'Hoy' con las 3 jugadas por plata, un semáforo que ya no linkea sino que razona alertas nuevas con IA sobre señales ya calculadas, y una bandeja de propuestas que aparece cuando NO estás mirando el chat (sin modal bloqueante salvo el auto-CRM). Se ve terminado cuando abrís MaKo a la mañana y sabés exactamente qué hacer, y si no lo hacés, te lo reclama.", "2026-09-20"),
  P("funnel-como-fuente", "🧭", "Funnel como fuente única de verdad", "#2F6FED", 8, "Convertir funnel_config (etapas + transiciones + bandas + triggers) en la definición formal del proceso comercial que TODO el resto consume, en vez de una panta", "Convertir funnel_config (etapas + transiciones + bandas + triggers) en la definición formal del proceso comercial que TODO el resto consume, en vez de una pantalla aislada. El editor, la derivación (generateFunnel), el rediseño conceptual (nutrición positiva derivada, No Show por reunión, Reunión excepcional) y Fathom como disparador ya existen; el norte es que MaKo, las métricas, los SLAs, la timeline y la nutrición dejen de hardcodear etapas y lean el funnel. Se ve terminado cuando agregar una etapa en /funnel se refleja sola en dashboards, reglas y contexto de IA sin tocar código.", "2026-08-30"),
  P("arranque-del-cliente", "🧳", "Arranque del cliente: onboarding + modo simple + mínima config", "#0E9B8E", 7, "Que un cliente nuevo se vuelva productivo con la menor fricción:", "Que un cliente nuevo se vuelva productivo con la menor fricción: un wizard bloqueante que lo lleva de integraciones → extracción histórica → tabs → negocio → Retro inicial; una vista SIMPLE por default (3 tareas + experimentos) con el kanban rico detrás de un toggle Avanzado; y el principio de pedir la MENOR config manual (defaults → plantillas → sugerencias → IA, el editor manual como último recurso). Importa porque es el gate para onboardear clientes reales sin un dashboard vacío ni abrumador. Se ve terminado cuando un cliente pasa el wizard solo, su histórico se extrae aunque cierre la pestaña, y ninguna pantalla lo obliga a 'armar' el sistema.", "2026-08-31"),
  P("motor-de-nutricin", "🤖", "Motor de nutrición multicanal + plantillas Meta", "#7C5CFB", 7, "El cerebro que decide y dispara la nutrición del lead según su etapa, con reglas anti-baneo (typing delay proporcional, pausas aleatorias, rate-limiter) sobre W", "El cerebro que decide y dispara la nutrición del lead según su etapa, con reglas anti-baneo (typing delay proporcional, pausas aleatorias, rate-limiter) sobre WhatsApp y Email compartiendo cohorte y guard de 20h/lead, más el sistema completo para redactar, validar y publicar plantillas de mensaje en Meta (validador IA → Graph API → estado → editar aprobadas). Importa porque convierte el funnel en acción sin intervención humana y sin plantillas aprobadas no hay forma de reabrir la ventana de 24h. Motor y plantillas completos en código; APAGADO en dry-run (el encendido real se trata en el go-live).", ""),
  P("bandejas-de-whatsapp", "📥", "Bandejas de WhatsApp (oficial Chatwoot + no oficial Evolution)", "#C8870C", 7, "El inbox de WhatsApp fiel a la app nativa sobre DOS canales:", "El inbox de WhatsApp fiel a la app nativa sobre DOS canales: el oficial (Cloud API vía Chatwoot, tráfico frío de ads) y el no oficial por QR (Evolution self-hosted, el número real de venta del cliente, sin las restricciones de la Cloud API). Leer/responder, multimedia, notas de voz, borradores, notificaciones en vivo, detalle del lead a un clic y paridad 1:1 entre ambos canales. Importa porque es donde el equipo conversa con los leads. Los dos canales están enviados; quedan las piezas F4 y el onboarding doer.", "2026-08-25"),
  P("cuentas-roles-y", "🔑", "Cuentas, roles y equipo (acceso multi-usuario)", "#D6489B", 6, "Reemplazar la contraseña compartida por cuentas reales con rol, sesión firmada, un flujo para cargar los tokens de cada integración, y roles de negocio por work", "Reemplazar la contraseña compartida por cuentas reales con rol, sesión firmada, un flujo para cargar los tokens de cada integración, y roles de negocio por workspace (admin-cliente/closer/setter) con enforcement server-side. Importa porque la contraseña única no distinguía agencia de cliente ni suspendía a nadie, y un closer no debe ver la facturación. Terminado cuando cada persona entra con su cuenta Google, el gate valida contra la DB por request, los tokens se cargan cifrados con tutorial, y el alta de cliente crea workspace+admin en un paso. Entregado en prod (migs 0053, 0058).", ""),
  P("mako-escribe-la", "🖋️", "MaKo escribe la nutrición + fábrica de writers", "#1E9E57", 7, "Que el cliente NO arme 30 mensajes:", "Que el cliente NO arme 30 mensajes: MaKo destila cómo comunica (de sus transcripts de ads + su marca), escribe cada paso de la nutrición en esa voz apoyándose en un cerebro de copywriting curado (metodología + swipe de ejemplos reales como few-shot), y él solo revisa/aprueba. La misma capa produce el Ad Copy Studio (copy de anuncios de Meta) y, a futuro, VSL Writer y DM Writer con el mismo patrón writer. Importa porque la nutrición es el punto ciego del cliente y multiplica el criterio de Martín a escala. F3 y Ad Copy están hechos; falta el go-live real y los writers de VSL/DM.", "2026-09-30"),
  P("sistema-de-contexto", "🧩", "Sistema de contexto de MaKo (RAG + prompts + fases + cursos)", "#98A0AC", 6, "El cimiento que hace que MaKo deje de responder genérico:", "El cimiento que hace que MaKo deje de responder genérico: buildSystemPrompt() ensambla de forma ADITIVA y resiliente persona + núcleo fijo + perfil del negocio + instrucción por sección + conocimiento recuperado (RAG por cursos/áreas) + datos del gráfico, omitiendo lo que falle. Todos los prompts del código (33, 10 grupos) son editables desde /configuraciones con {{slots}} e historial. Le da metodología, perfil e instrucciones por pantalla sin deploy. Construido al ~90%; falta enchufar los números vivos (compartido con Tool-Use Core), registrar los prompts de Experimentos/Retro y migrar el RAG a pgvector.", "2026-08-15"),
  P("closing-analyst-analista", "📞", "Closing Analyst — analista de llamadas de venta", "#D0504A", 6, "Vista /closing que trae las llamadas históricas de Fathom, las matchea con leads por email, distingue VENTA (R1/R2) de ENTREGA DE SERVICIO (coaching a clientes ", "Vista /closing que trae las llamadas históricas de Fathom, las matchea con leads por email, distingue VENTA (R1/R2) de ENTREGA DE SERVICIO (coaching a clientes cerrados) y corre Opus para puntuar SPIN + ejecución, momentos clave, objeciones y next step. Importa porque Mauricio graba TODO en Fathom y solo ~10-40 de ~196 llamadas son ventas reales: sin el árbitro de Claude, las sesiones de servicio contaminaban el análisis y los links R1/R2 del lead. Entregado (v2, mig 0038): dos vistas (Métricas + Llamadas con grabación embebida), score robusto y R1/R2 re-linkeados solo con ventas.", ""),
  P("script-analyst-analista", "🎬", "Script Analyst — analista de guiones de video ads", "#2F6FED", 6, "Vista /script-analyst que cruza el análisis cualitativo de Claude (ángulo, hook, formato, beats, diagnóstico) con la retención de Meta por cuartiles y las agend", "Vista /script-analyst que cruza el análisis cualitativo de Claude (ángulo, hook, formato, beats, diagnóstico) con la retención de Meta por cuartiles y las agendas/cierres del CRM. Importa porque separa lo que envejece (métricas vivas, nunca guardadas) de lo estable (lectura estructural del guion, 1 fila por ad_id), así un guion se juzga por su desempeño ACUMULADO. Entregado (migs 0039-0042, 55 guiones): Patrones, Cuadrante de retención calibrado, valorador de guion nuevo con historial, taxonomía editable de ángulos/avatares e imágenes por OCR. Queda solo limpieza de código muerto y un board alternativo.", "2026-07-25"),
  P("board-plan-perro", "🐕", "Board /plan — Perro Guardián", "#0E9B8E", 6, "El tablero fuente-de-verdad del backlog:", "El tablero fuente-de-verdad del backlog: rebuild del viejo /martinkoncke a un board estilo Trello (renombrado /plan) con proyectos como entidad de primera clase, columnas de prioridad fijas, checklists que derivan el avance, change history y un componente unificado admin↔cliente. Encima, un 'Perro Guardián' (MaKo) que prioriza al crear, debate encadenado, curva las tareas a una pirámide sana y spread de prioridad de proyectos 1-10 sin empates. Importa porque es donde se planifica y prioriza TODO el roadmap. Entregado y poblado con el roadmap minado de la memoria; solo quedan cierres de dev.", ""),
  P("experimentos-como-fuente", "🧪", "Experimentos como fuente de verdad + auto-cierre", "#7C5CFB", 6, "El único lugar donde MaKo concluye con DATOS:", "El único lugar donde MaKo concluye con DATOS: convierte una hipótesis en experimento medible (baseline, medición determinística en vivo, veredicto al cerrar). La regla 'MaKo nunca concluye, sugiere abrir experimento' vive en el núcleo (MAKO_NUCLEO) y resumenExperimentos() inyecta al system prompt solo las verdades validadas. El ciclo, la medición y el rediseño en 3 tabs ya están; falta el combustible (atribución de cash por anuncio, histórico de veredictos de ads) y automatizar el cierre (cron) y las ideas huérfanas. Se ve terminado cuando los experimentos se cierran solos y las decisiones se apoyan en cash real por creativo.", "2026-09-30"),
  P("rplica-de-meta", "📋", "Réplica de Meta Ads Manager + escrituras a Meta", "#C8870C", 5, "Un Ads Manager propio dentro de MaKo:", "Un Ads Manager propio dentro de MaKo: navegar campañas/conjuntos/anuncios como en Meta y ESCRIBIR de vuelta (pausar/activar, presupuesto, renombrar en lote con nomenclatura, editar público/anuncio/conjunto) sin salir de la app. Importa porque cierra el loop 'ver→decidir→accionar' que un dashboard read-only no da. Entregado y verificado con 27 campañas reales: cada write llega a Meta con manejo de error real (Meta responde 200 con error), gateado owner-only, y el renombrado en lote aplica nomenclatura jerárquica consistente.", ""),
  P("cerrar-el-ciclo", "🎯", "Cerrar el ciclo con Meta (nueva campaña + salud + CAPI Purchase)", "#D6489B", 5, "Las tres piezas que faltan para operar Meta de punta a punta desde MaKo:", "Las tres piezas que faltan para operar Meta de punta a punta desde MaKo: el creador de campañas 'Nueva campaña' (describís + adjuntás creativos → MaKo propone un CampaignSpec → editás → publica en PAUSA), la vista de salud de cuenta ('¿el sistema está entregando?') con recomendaciones derivadas por MaKo, y el evento Purchase por Conversions API al cobrar (el hito de valor que cierra el loop de atribución). Se ve terminado cuando se publica el árbol completo con conversión por evento activo, la salud recomienda proactivamente, y Meta optimiza sobre el dinero cobrado.", "2026-08-15"),
  P("comunicacin-con-el", "🔔", "Comunicación con el dueño + señales de WhatsApp", "#1E9E57", 5, "Que el dueño reciba lo urgente y los resúmenes por su canal preferido (WhatsApp/email/Telegram), pueda RESPONDER y que MaKo ejecute ('sí, hazlo' → pausar campañ", "Que el dueño reciba lo urgente y los resúmenes por su canal preferido (WhatsApp/email/Telegram), pueda RESPONDER y que MaKo ejecute ('sí, hazlo' → pausar campañas), y que el CRM 'sienta' lo que pasa en WhatsApp (última respuesta, toques, número que contactó). Importa porque convierte los reportes en acción sin abrir la app y habilita el no_responde automático, los SLAs y el orden del worklist. El /perfil, el centro de notificaciones y los reportes para el dueño están hechos; falta que los crons iteren workspaces, el handler inbound accionable y las señales granulares por lead.", "2026-08-30"),
  P("reskin-de-la", "🎨", "Reskin de la app + branding MaKo", "#98A0AC", 5, "Llevar toda la app a un look coherente y limpio alineado con la landing /vsl y los ports de Claude Design pantalla por pantalla (Marketing OS light theme, Funne", "Llevar toda la app a un look coherente y limpio alineado con la landing /vsl y los ports de Claude Design pantalla por pantalla (Marketing OS light theme, Funnel, Closing/Script Analyst, Retro), con el sidebar plegable en grupos, la identidad MaKo (logo, voz rioplatense, ChartIA envolviendo cada gráfico) y el copy migrado a R1/R2. Importa porque una app dispar se siente 'a medio hacer' y frena la adopción; es transversal y continuo. Se ve terminado cuando no queda ninguna pantalla con el estilo viejo ni ningún gráfico sin su ✦ MaKo. Mayormente hecho (~75%).", "2026-09-30"),
  P("landing-de-venta", "🌐", "Landing de venta /vsl + páginas de detalle + atribución VSL", "#D0504A", 5, "La cara comercial pública de MaKo:", "La cara comercial pública de MaKo: la landing /vsl (port del diseño de Claude Design, no HTML a mano) con VSL en el hero y CTA que agenda por Calendly, las 15 páginas de detalle por feature (/vsl/<slug>, estilo VTurb), y la cadena de identificación que convierte a un espectador anónimo del VSL en un lead atribuido con todo su comportamiento. Importa porque es cómo se vende el producto y cómo se mide el tráfico. El core de la landing y el backend de atribución están en prod; el cuello real es que Martín pegue el snippet en Lovable y arme el flujo de WhatsApp, más completar placeholders de las páginas de detalle.", "2026-08-15"),
  P("skills-de-claude", "🛠️", "Skills de Claude Code + Graphify + gasto de IA", "#2F6FED", 4, "El tooling de dev-time y de medición que hace a MaKo un producto autónomo y barato de construir:", "El tooling de dev-time y de medición que hace a MaKo un producto autónomo y barato de construir: skills a medida del repo (SKILL.md en .claude/skills) + públicas selectas de skills.sh, un knowledge graph del código (Graphify) que sí funciona sobre este TypeScript, y el registro de gasto/costo de IA por operación con saldo prepago manual. Importa porque acelera la construcción (evita leaks de tenant, key-drift de prompts) y da transparencia del costo de cada feature. Entregado y pusheado; lo que queda es aplicar las skills como hábito.", ""),
  P("growth-vender-mako", "📣", "Growth — vender MaKo hacia afuera", "#0E9B8E", 3, "El marketing del PRODUCTO (no el producto):", "El marketing del PRODUCTO (no el producto): venderle MaKo a todo el que corra un VSL Funnel. Incluye la Oferta Cebolla (planes por nivel que limitan acceso según la situación del lead), miles de ads por cada funcionalidad (modelo Claudio Conde), testimonios, thank-you page post-agenda, demos por feature y mapa de calor de uso. Importa para crecer, pero deliberadamente va DESPUÉS de que el producto esté DOER de verdad: vender algo a medio hacer quema pólvora y reputación. Por eso casi todo es 'futuro', prioridad baja.", ""),
  P("infraestructura-propia-e", "🧰", "Infraestructura propia + escala de mensajería", "#7C5CFB", 2, "El trabajo de plataforma de fondo que hace a MaKo autónomo de la agencia y listo para muchos clientes:", "El trabajo de plataforma de fondo que hace a MaKo autónomo de la agencia y listo para muchos clientes: mover Supabase/Vercel/dominio a nombre propio (landing en la raíz, no /vsl), un protocolo para versionar sin interrumpir betas, y keys propias por workspace para Resend/Evolution (hoy usan una cuenta ÚNICA de MaKo que topa en los límites de entrega al escalar). Importa a mediano plazo pero hoy nada lo bloquea. Se ve terminado cuando MaKo corre en infra propia, con release ordenado, y cada workspace en volumen carga su propia key. Muy a futuro, prioridad baja.", ""),
  P("canales-fros-bot", "🧊", "Canales fríos: bot de contención + inbound-first + IG + email inbox", "#C8870C", 3, "Completar el esquema híbrido de 3 números y los canales de entrada fríos:", "Completar el esquema híbrido de 3 números y los canales de entrada fríos: un bot oficial que contiene el tráfico frío de ads antes de pasarlo al no oficial de venta, inbound-first (wa.me con keyword + QR en vivo) que baja el riesgo de baneo ~90%, Instagram DMs en el inbox unificado y un inbox de email por lead. Importa para escalar la captación sin quemar el número de empresa, pero es de arranque lejano y depende de que el resto esté DOER. Se ve terminado cuando el tráfico frío entra por el bot y el inbound reduce el baneo. Todo en estado stub/futuro.", ""),
  P("dashboard-de-analtica", "📊", "Dashboard de analítica de marketing (Marketing OS) — el núcleo de reporte", "#D6489B", 6, "El producto original y cimiento de todo lo demás:", "El producto original y cimiento de todo lo demás: el tablero que convierte Meta + Calendly + YouTube/Panda + pagos en vistas de decisión — Vista General ('tu norte' con objetivo + pacing + ETA), Marketing (CAC en 3 niveles, ROAS, resumen de cuenta, Tendencias multi-serie, Anuncios Ganadores con ReconVeredicto), Comercial (cohortes maduras, SCL, no-show) y Revenue/Cobranza (Sold/Cash/Outstanding, plan de cuotas, contrato leído por IA, 'a quién cobrarle'). Importa porque es la capa de números confiables sobre la que MaKo razona: sin esto no hay doer ni semáforo ni Retro. Se ve 'terminado' con todas las tabs vivas, KPIs clickeables con desglose por lead, filtro de fecha global persistente y pase mobile — estado: enviado end-to-end (commits de mayo a junio 2026).", ""),
  P("cimientos-de-datos", "🔌", "Cimientos de datos: conectores + ingesta multi-fuente", "#1E9E57", 5, "La capa de tuberías que alimenta todo el resto:", "La capa de tuberías que alimenta todo el resto: conectores a Meta Ads (insights a nivel anuncio + presupuestos de adsets), Meta Lead Ads (webhook + match por teléfono), Calendly (webhook + backfill histórico como leads), YouTube (Data API + Analytics API para el VSL), Panda Video (fuente del VSL actual) y CAPI (eventos Lead / QualifiedLead / Schedule). Importa porque sin ingesta confiable y backfills históricos ninguna vista ni MaKo tiene con qué razonar. Terminado = cada fuente con webhook + polling diario de red de seguridad + backfills corridos; estado: enviado (la ingesta por-workspace se completa en el proyecto multi-inquilino).", ""),
  P("cs-analyst-analista", "🩺", "CS Analyst — analista de Customer Success / retención", "#98A0AC", 6, "El gemelo del Closing Analyst pero sobre las llamadas de ENTREGA de servicio, que hoy se transcriben y se tiran (category=entrega_servicio, status=descartada, a", "El gemelo del Closing Analyst pero sobre las llamadas de ENTREGA de servicio, que hoy se transcriben y se tiran (category=entrega_servicio, status=descartada, analysis null). Importa porque es la tab net-new más rentable y barata (D2 según el roadmap): reusa 1:1 la infra de transcripción/análisis del Closing y le suma un Health Score de churn (sentimiento de la última llamada × cuota impaga × señales) para anticipar bajas en la cartera antes de que se vayan. Terminado = llamadas de servicio analizadas con resumen/riesgos/próximos pasos, un Health Score por cliente y alertas de churn accionables al dueño. Estado: no arrancado (los datos ya existen, solo se descartan).", "2026-09-15"),
  P("agente-de-ads", "📈", "Agente de Ads — MaKo optimiza el gasto solo (con tu OK)", "#D0504A", 5, "Cerrar el loop entre gasto y cash real:", "Cerrar el loop entre gasto y cash real: que MaKo proponga (y con tu OK ejecute) escalar el presupuesto de los anuncios ganadores, apagar los que queman plata y duplicar ganadores, usando la atribución de cash por anuncio como brújula en vez de solo leads. Importa porque es la palanca de ROI más directa ahora que las escrituras a Meta ya funcionan y el tool-use está vivo. Terminado = reglas de escalado/apagado propuestas con datos + ejecución en 1 clic con rastro en audit log, y persistencia del histórico de veredictos para detectar quema de dinero en el tiempo. Estado: piezas listas (writes Meta OK, ReconVeredicto, atribución de cash), falta el agente que las orquesta.", "2026-10-01"),
  P("copiloto-en-vivo", "🎧", "Copiloto en vivo de la llamada (STT streaming)", "#2F6FED", 2, "Moonshot:", "Moonshot: un copiloto que escucha la llamada de venta en tiempo real (speech-to-text streaming) y le sugiere al closer respuestas y manejo de objeciones mientras habla, alimentado por el cerebro de copywriting/closing ya curado. Importa como diferenciador máximo del producto, pero es el único de todo el roadmap que pega contra algo inexistente en el stack: hoy no hay ninguna capa de STT en vivo. Terminado = transcripción en vivo de R1/R2 + sugerencias contextuales de baja latencia durante la llamada. Estado: idea, sin arrancar; queda lejos por dificultad (D5) y costo.", ""),
];

